char bf[1<<21],CC[55];int _p,P_=-1;
void flush(){fwrite(bf,1,P_+1,stdout);P_=-1;}
inline void pus(const char *_k,char ch='\n'){
	for(int i=0;i<(int)strlen(_k);i++)bf[++P_]=_k[i];
